index bf9310a..86a393c 100644
--- a/src/store.ts
+++ b/src/store.ts
@@ -9,7 +9,12 @@ export interface Row<T> {

 const rows = new Map<string, Row<unknown>>();

+// Memo cache for values derived from store rows. Any mutation (put/del) drops
+// all entries, so cached derivations never outlive the rows they came from.
+const cache = new Map<string, unknown>();
+
 export function put<T>(id: string, value: T): Row<T> {
+  cache.clear();
   const row: Row<T> = { id, value, updatedAt: Date.now() };
   rows.set(id, row as Row<unknown>);
   return row;
@@ -19,7 +24,18 @@ export function get<T>(id: string): Row<T> | undefined {
   return rows.get(id) as Row<T> | undefined;
 }

+// Memoizes `compute` per key: the first call stores the result, later calls
+// return it without recomputing. A cached `undefined` is honoured; a throwing
+// `compute` stores nothing.
+export function getCached<T>(key: string, compute: () => T): T {
+  if (cache.has(key)) return cache.get(key) as T;
+  const value = compute();
+  cache.set(key, value);
+  return value;
+}
+
 export function del(id: string): boolean {
+  cache.clear();
   return rows.delete(id);
 }

@@ -37,6 +53,7 @@ export function size(): number {

 export function clear(): void {
   rows.clear();
+  cache.clear();
 }

